-- Affectation des DCI aux produits a partir du fichier recupDCI.xlsx (19304 lignes).
--
-- Pour chaque produit de la base, la DCI du fichier (PBDCIC / DCLIB) est retenue quand le produit est reconnu :
--   1. par PICODE      (compare au CIP, a l'EAN 13 et aux CIP2, CIP3, CIP4 du produit) ;
--   2. sinon par PSACIP (ancien code, memes colonnes) ;
--   3. sinon par le libelle PSLIBPSLIBC (compare au nom du produit, sans tenir compte des majuscules).
-- La regle la plus sure l'emporte. Si, a ce meme niveau, deux lignes du fichier donnent deux DCI differentes, le
-- produit n'est PAS modifie : il est liste a l'etape 3.
--
-- La DCI est cherchee par son code PBDCIC ; a defaut, par son nom DCLIB (une DCI de meme nom deja en base est
-- reprise telle quelle) ; a defaut, elle est creee (code PBDCIC, nom DCLIB). Un code absent de la base ET sans
-- libelle dans le fichier n'est pas cree : ses produits ne sont pas modifies.
--
-- « Mettre a jour la DCI » d'un produit : il garde la DCI du fichier et elle seule (ses autres liens DCI sont
-- retires). Les liens sont sauvegardes avant (t_famille_dci_sauvegarde_recup) ; retour en arriere en fin de fichier.
--
-- ORDRE CONSEILLE : dci_2026_maj_codes.sql, puis dci_2026_sans_doublons.sql, puis ce script.
-- MODE D'EMPLOI : lancer les etapes une par une ; seule l'etape 4 modifie le logiciel. SQL simple, compatible avec
-- les anciens serveurs (ni WITH, ni fonctions de fenetre). Fichier en UTF-8 : l'ouvrir en UTF-8 dans HeidiSQL.

SET NAMES utf8;

-- ============================================================================================
-- ETAPE 1 : chargement du fichier dans une table de travail
-- ============================================================================================
-- Colonnes creees a partir des tables du logiciel : memes jeux de caracteres, comparaisons sans conflit.
DROP TABLE IF EXISTS recup_dci;
CREATE TABLE recup_dci AS
SELECT 0 AS ligne, f.int_CIP AS picode, f.int_CIP AS psacip, f.str_NAME AS libelle,
       d.str_CODE AS dci_code, d.str_NAME AS dci_libelle
FROM t_famille f, t_dci d WHERE 1 = 0;
ALTER TABLE recup_dci ADD INDEX recup_picode (picode), ADD INDEX recup_psacip (psacip),
                      ADD INDEX recup_libelle (libelle), ADD INDEX recup_code (dci_code);


SELECT COUNT(*) AS lignes_chargees FROM recup_dci;


-- ============================================================================================
-- ETAPE 2 : DCI du fichier -> DCI de la base (rien n'est encore modifie dans le logiciel)
-- ============================================================================================
DROP TABLE IF EXISTS recup_dci_codes;
CREATE TABLE recup_dci_codes AS
SELECT r.dci_code, MAX(r.dci_libelle) AS dci_libelle, MIN(r.ligne) AS premiere_ligne,
       d.lg_DCI_ID AS lg_DCI_ID, CAST('code' AS CHAR(10)) AS origine
FROM recup_dci r LEFT JOIN t_dci d ON d.str_CODE = r.dci_code
GROUP BY r.dci_code, d.lg_DCI_ID;

-- Code absent : DCI de meme nom deja en base (la DCI active, puis la plus ancienne).
UPDATE recup_dci_codes c
SET c.lg_DCI_ID = (SELECT d.lg_DCI_ID FROM t_dci d
                   WHERE REPLACE(d.str_NAME, ' ', '') = REPLACE(c.dci_libelle, ' ', '')
                   ORDER BY (d.str_STATUT = 'enable') DESC, d.dt_CREATED, d.lg_DCI_ID LIMIT 1),
    c.origine = 'nom'
WHERE c.lg_DCI_ID IS NULL AND c.dci_libelle <> '';
UPDATE recup_dci_codes SET origine = 'a creer' WHERE lg_DCI_ID IS NULL AND dci_libelle <> '';
-- Code absent ET sans libelle dans le fichier : ni cherchee ni creee ; ses produits ne sont pas modifies.
UPDATE recup_dci_codes SET origine = 'sans nom' WHERE lg_DCI_ID IS NULL AND dci_libelle = '';

SELECT origine, COUNT(*) AS dci FROM recup_dci_codes GROUP BY origine;
-- DCI reprises par leur nom (elles gardent leur code actuel), DCI qui seront creees, et DCI sans libelle dans le
-- fichier (« sans nom » : leurs produits ne sont pas modifies) :
SELECT c.dci_code AS code_fichier, c.dci_libelle, c.origine, d.str_CODE AS code_en_base, d.str_NAME AS nom_en_base
FROM recup_dci_codes c LEFT JOIN t_dci d ON d.lg_DCI_ID = c.lg_DCI_ID
WHERE c.origine <> 'code' ORDER BY c.origine, c.dci_code;


-- ============================================================================================
-- ETAPE 3 : produits reconnus et DCI retenue (rien n'est encore modifie dans le logiciel)
-- ============================================================================================
DROP TABLE IF EXISTS recup_dci_candidats;
CREATE TABLE recup_dci_candidats AS
SELECT f.lg_FAMILLE_ID, 1 AS rang, r.dci_code FROM t_famille f JOIN recup_dci r ON r.picode = f.int_CIP
UNION SELECT f.lg_FAMILLE_ID, 1, r.dci_code FROM t_famille f JOIN recup_dci r ON r.picode = f.int_EAN13
UNION SELECT f.lg_FAMILLE_ID, 1, r.dci_code FROM t_famille f JOIN recup_dci r ON r.picode = f.int_CIP2
UNION SELECT f.lg_FAMILLE_ID, 1, r.dci_code FROM t_famille f JOIN recup_dci r ON r.picode = f.int_CIP3
UNION SELECT f.lg_FAMILLE_ID, 1, r.dci_code FROM t_famille f JOIN recup_dci r ON r.picode = f.int_CIP4
UNION SELECT f.lg_FAMILLE_ID, 2, r.dci_code FROM t_famille f JOIN recup_dci r ON r.psacip = f.int_CIP WHERE r.psacip <> ''
UNION SELECT f.lg_FAMILLE_ID, 2, r.dci_code FROM t_famille f JOIN recup_dci r ON r.psacip = f.int_EAN13 WHERE r.psacip <> ''
UNION SELECT f.lg_FAMILLE_ID, 2, r.dci_code FROM t_famille f JOIN recup_dci r ON r.psacip = f.int_CIP2 WHERE r.psacip <> ''
UNION SELECT f.lg_FAMILLE_ID, 2, r.dci_code FROM t_famille f JOIN recup_dci r ON r.psacip = f.int_CIP3 WHERE r.psacip <> ''
UNION SELECT f.lg_FAMILLE_ID, 2, r.dci_code FROM t_famille f JOIN recup_dci r ON r.psacip = f.int_CIP4 WHERE r.psacip <> ''
UNION SELECT f.lg_FAMILLE_ID, 3, r.dci_code FROM t_famille f JOIN recup_dci r ON r.libelle = TRIM(f.str_NAME) WHERE r.libelle <> '';

-- Meilleure regle par produit, et nombre de DCI differentes a ce niveau.
DROP TABLE IF EXISTS recup_dci_produits;
CREATE TABLE recup_dci_produits AS
SELECT c.lg_FAMILLE_ID, c.rang, COUNT(DISTINCT c.dci_code) AS nb_dci, MIN(c.dci_code) AS dci_code
FROM recup_dci_candidats c
JOIN (SELECT lg_FAMILLE_ID, MIN(rang) AS rang FROM recup_dci_candidats GROUP BY lg_FAMILLE_ID) m
  ON m.lg_FAMILLE_ID = c.lg_FAMILLE_ID AND m.rang = c.rang
GROUP BY c.lg_FAMILLE_ID, c.rang;

-- 3a. Bilan : produits reconnus par regle ; ambigus (non modifies). Les produits dont la DCI est « sans nom »
--     (etape 2) sont comptes ici mais ne seront pas modifies.
SELECT CASE rang WHEN 1 THEN '1-PICODE' WHEN 2 THEN '2-PSACIP' ELSE '3-LIBELLE' END AS regle,
       SUM(nb_dci = 1) AS produits_mis_a_jour, SUM(nb_dci > 1) AS produits_ambigus_non_modifies
FROM recup_dci_produits GROUP BY rang ORDER BY rang;

-- 3b. Produits ambigus : deux DCI possibles au meme niveau. A traiter a la main si besoin.
SELECT f.int_CIP, f.str_NAME, p.rang, GROUP_CONCAT(DISTINCT c.dci_code) AS dci_possibles
FROM recup_dci_produits p
JOIN t_famille f ON f.lg_FAMILLE_ID = p.lg_FAMILLE_ID
JOIN recup_dci_candidats c ON c.lg_FAMILLE_ID = p.lg_FAMILLE_ID AND c.rang = p.rang
WHERE p.nb_dci > 1
GROUP BY f.lg_FAMILLE_ID, f.int_CIP, f.str_NAME, p.rang;

-- 3c. Apercu : 50 produits avec leur DCI actuelle et la DCI retenue.
SELECT f.int_CIP, f.str_NAME, p.rang,
       (SELECT GROUP_CONCAT(d.str_NAME) FROM t_famille_dci fd JOIN t_dci d ON d.lg_DCI_ID = fd.lg_DCI_ID
         WHERE fd.lg_FAMILLE_ID = p.lg_FAMILLE_ID) AS dci_actuelle,
       c.dci_code AS dci_retenue, c.dci_libelle
FROM recup_dci_produits p
JOIN t_famille f ON f.lg_FAMILLE_ID = p.lg_FAMILLE_ID
JOIN recup_dci_codes c ON c.dci_code = p.dci_code
WHERE p.nb_dci = 1
ORDER BY f.str_NAME LIMIT 50;


-- ============================================================================================
-- ETAPE 4 : mise a jour (SAUVEGARDE DE LA BASE FAITE AVANT) - sans effet si on la relance
-- ============================================================================================
-- Sauvegarde des liens produit -> DCI (une seule fois : un second passage ne l'ecrase pas).
CREATE TABLE IF NOT EXISTS t_famille_dci_sauvegarde_recup AS SELECT * FROM t_famille_dci;

START TRANSACTION;

-- DCI manquantes : creees avec le code et le nom du fichier.
SELECT CONCAT('98', LPAD(CONV(LEFT(MD5(c.dci_code), 14), 16, 10), 18, '0')), c.dci_code, c.dci_libelle,
       'enable', NOW(), NULL
FROM recup_dci_codes c
WHERE c.lg_DCI_ID IS NULL AND c.dci_libelle <> ''
  AND NOT EXISTS (SELECT 1 FROM t_dci d WHERE d.str_CODE = c.dci_code);
UPDATE recup_dci_codes c JOIN t_dci d ON d.str_CODE = c.dci_code
SET c.lg_DCI_ID = d.lg_DCI_ID
WHERE c.lg_DCI_ID IS NULL;

-- Autres DCI des produits mis a jour : retirees.
DELETE fd FROM t_famille_dci fd
JOIN (SELECT p.lg_FAMILLE_ID, c.lg_DCI_ID FROM recup_dci_produits p JOIN recup_dci_codes c ON c.dci_code = p.dci_code WHERE p.nb_dci = 1 AND c.lg_DCI_ID IS NOT NULL) l ON l.lg_FAMILLE_ID = fd.lg_FAMILLE_ID
WHERE fd.lg_DCI_ID <> l.lg_DCI_ID;

-- DCI du fichier : liee si elle ne l'est pas deja.
SELECT CONCAT('99', LPAD(CONV(LEFT(MD5(CONCAT(l.lg_FAMILLE_ID, '|', l.lg_DCI_ID)), 14), 16, 10), 18, '0')),
       l.lg_FAMILLE_ID, l.lg_DCI_ID, 'enable', NOW(), NULL
FROM (SELECT p.lg_FAMILLE_ID, c.lg_DCI_ID FROM recup_dci_produits p JOIN recup_dci_codes c ON c.dci_code = p.dci_code WHERE p.nb_dci = 1 AND c.lg_DCI_ID IS NOT NULL) l
WHERE NOT EXISTS (SELECT 1 FROM t_famille_dci fd
                  WHERE fd.lg_FAMILLE_ID = l.lg_FAMILLE_ID AND fd.lg_DCI_ID = l.lg_DCI_ID);

-- Un lien deja present mais desactive est reactive.
UPDATE t_famille_dci fd JOIN (SELECT p.lg_FAMILLE_ID, c.lg_DCI_ID FROM recup_dci_produits p JOIN recup_dci_codes c ON c.dci_code = p.dci_code WHERE p.nb_dci = 1 AND c.lg_DCI_ID IS NOT NULL) l
  ON l.lg_FAMILLE_ID = fd.lg_FAMILLE_ID AND l.lg_DCI_ID = fd.lg_DCI_ID
SET fd.str_STATUT = 'enable', fd.dt_UPDATED = NOW()
WHERE IFNULL(fd.str_STATUT, '') NOT IN ('', 'enable');

COMMIT;


-- ============================================================================================
-- ETAPE 5 : verification
-- ============================================================================================
SELECT COUNT(*) AS produits_a_mettre_a_jour,
       SUM(EXISTS (SELECT 1 FROM t_famille_dci fd WHERE fd.lg_FAMILLE_ID = l.lg_FAMILLE_ID
                   AND fd.lg_DCI_ID = l.lg_DCI_ID AND IFNULL(fd.str_STATUT, 'enable') IN ('', 'enable'))) AS avec_la_dci_du_fichier,
       SUM((SELECT COUNT(*) FROM t_famille_dci fd WHERE fd.lg_FAMILLE_ID = l.lg_FAMILLE_ID) = 1) AS avec_cette_seule_dci
FROM (SELECT p.lg_FAMILLE_ID, c.lg_DCI_ID FROM recup_dci_produits p JOIN recup_dci_codes c ON c.dci_code = p.dci_code WHERE p.nb_dci = 1 AND c.lg_DCI_ID IS NOT NULL) l;
-- Les tables de travail (recup_dci, recup_dci_codes, recup_dci_candidats, recup_dci_produits)
-- peuvent etre supprimees une fois le resultat valide. Garder t_famille_dci_sauvegarde_recup tant qu'un retour en
-- arriere peut etre utile.


-- ============================================================================================
-- RETOUR EN ARRIERE (uniquement si besoin) : remet les liens produit -> DCI d'avant l'etape 4
-- ============================================================================================
-- START TRANSACTION;
